package com.chesspulseai.entity;
import com.chesspulseai.enumtype.PlayerColor; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="moves",uniqueConstraints=@UniqueConstraint(name="uk_game_move",columnNames={"game_id","moveNumber"})) public class ChessMove { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="game_id",nullable=false) private Game game; @Column(nullable=false) private int moveNumber; @Column(nullable=false,length=20) private String san; @Column(nullable=false,length=5) private String uci; @Column(nullable=false,length=120) private String fen; @Enumerated(EnumType.STRING) @Column(nullable=false) private PlayerColor playerColor; @Column(nullable=false,updatable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; @OneToOne(mappedBy="move",cascade=CascadeType.ALL,orphanRemoval=true) private PositionAnalysis analysis; @PrePersist void created(){createdAt=updatedAt=Instant.now();}@PreUpdate void updated(){updatedAt=Instant.now();} public Long getId(){return id;} public Game getGame(){return game;} public void setGame(Game v){game=v;} public int getMoveNumber(){return moveNumber;} public void setMoveNumber(int v){moveNumber=v;} public String getSan(){return san;} public void setSan(String v){san=v;} public String getUci(){return uci;} public void setUci(String v){uci=v;} public String getFen(){return fen;} public void setFen(String v){fen=v;} public PlayerColor getPlayerColor(){return playerColor;} public void setPlayerColor(PlayerColor v){playerColor=v;} public PositionAnalysis getAnalysis(){return analysis;} public void setAnalysis(PositionAnalysis v){analysis=v;} }
